<template>
  <div class="qv-workspace" :class="{'qv-director-mode':videoToolMode(form.mode)}">
    <header class="qv-hero"><div><span class="qv-eyebrow">QGAUSS / MOTION STUDIO</span><h1>{{ vt(toolHero[form.mode]?.first) || vt("给想象，") }}<em>{{ vt(toolHero[form.mode]?.second) || vt("加一点时间。") }}</em></h1><p>{{ vt("一束光，一次运镜，一个值得反复播放的小世界。") }}</p><span class="qv-live"><i></i>{{ activeCount ? vt("{p0} 条创意正在片场",{p0:(activeCount)}) : vt("下一幕，由你开场") }}</span></div><div class="qv-sculpture" aria-hidden="true"><span class="qv-orbit"></span><span class="qv-film qv-film-back">Q</span><span class="qv-film qv-film-main"><i>▶</i><b>MOTION / 01</b></span><span class="qv-glint">✦</span></div></header>
    <GalleryEntryNotice :entry="galleryEntry" />
    <section class="qv-desk" :aria-label="vt(&quot;视频创作台&quot;)">
      <div class="qv-section-head"><span>01 / DIRECT YOUR IDEA</span><h2>{{ vt("你的下一幕") }}</h2><ClientIcon name="video" /></div>
      <div v-if="optionsError" class="qv-alert" role="alert">{{ vt(optionsError) }}<button type="button" @click="loadOptions">{{ vt("重新加载") }}</button></div>
      <div v-else-if="!optionsLoaded" class="qv-loading"><BrandLoader :text="vt(&quot;正在打开片场…&quot;)" /></div>
      <template v-else>
        <div v-if="!presets.some(p => p.ready)" class="qv-unconfigured"><span>✦</span><b>{{ vt("片场正在等待连接") }}</b><p>{{ vt("视频连接准备好后，就可以从这里开机。草稿可以先写好。") }}</p><RouterLink v-if="auth.isAdmin" to="/video/manage">{{ vt("前往视频控制台 ↗") }}</RouterLink></div>
        <label class="qv-field">{{ vt("创作模型") }}<select v-model="form.presetId" :aria-label="vt(&quot;视频创作模型&quot;)" :disabled="materialBusy || quoting || submitting"><option value="" disabled>{{ vt("选择一个创作模型") }}</option><option v-if="form.presetId&&!selected" :value="form.presetId" disabled>{{ vt("原创作模型已不可用，请重新选择") }}</option><option v-for="p in presets" :key="p.id" :value="p.id" :disabled="!p.ready">{{ p.name }}{{ p.ready ? '' : vt(" · 未就绪") }}</option></select><small v-if="selected">{{ vt(selected.reason || selected.caption) }}</small></label>
        <div class="qv-modes" :aria-label="vt(&quot;视频创作方式&quot;)"><button v-for="m in modeChoices" :key="m.key" type="button" :aria-pressed="form.mode === m.key" :disabled="materialBusy || quoting || submitting || selected && !selected.features.modes.includes(m.key)" @click="form.mode = m.key">{{ vt(m.label) }}</button></div>
        <div class="qv-prompt-head"><label for="qv-prompt">{{ ['upscale','lipsync'].includes(form.mode) ? vt("作品备注（可选）") : vt("描述这一幕") }}</label><small>{{ form.prompt.length }} / 4000</small></div><textarea id="qv-prompt" v-model="form.prompt" :readonly="legacyExtend" rows="5" maxlength="4000" :placeholder="vt(&quot;主体做什么？镜头如何移动？试着加一点光线、节奏和氛围…&quot;)"></textarea>
        <section v-if="form.mode === 'image'" class="qv-reference" :aria-label="vt(&quot;视频参考图&quot;)"><div v-for="(item, i) in references" :key="item.id" class="qv-ref-item"><img v-if="referenceUrl(item)" :src="referenceUrl(item)" :alt="i ? vt(&quot;视频尾帧参考&quot;) : vt(&quot;视频首帧参考&quot;)" /><span>{{ i ? vt("尾帧") : vt("首帧") }}</span><button type="button" :aria-label="vt(&quot;移除视频参考图 {p0}&quot;,{p0:(i + 1)})" :disabled="uploading" @click="removeReference(i)">×</button></div><button v-if="references.length < (selected?.features.maxImages || 1)" type="button" class="qv-add-reference" :disabled="uploading" @click="fileInput?.click()"><ClientIcon name="plus" />{{ uploading ? vt("上传中…") : references.length ? vt("加入尾帧") : vt("加入首帧参考") }}</button><small>{{ vt("本人静态图片，每张最多 10 MB / 约 800 万像素。生成时发送给所选服务。") }}</small></section>
        <input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden @change="uploadReferences" />
        <VideoMaterialBoard v-show="videoToolMode(form.mode)" v-model="materials" v-model:speaker-selection="speakerSelection" :mode="form.mode" :features="selected?.features" :movies="materialMovies" :disabled="quoting || submitting" @busy="materialBusy = $event"/>
        <fieldset v-if="form.mode === 'upscale'" class="qv-tools-parameters"><legend>{{ vt("把细节，慢慢找回来") }}</legend><label class="qv-field">{{ vt("精修模型") }}<select v-model="form.enhanceModel" :aria-label="vt(&quot;视频精修模型&quot;)"><option v-for="model in upscaleModels" :key="model" :value="model">{{ model }}</option></select></label><label class="qv-field">{{ vt("放大倍率 ") }}<b>{{ form.upscaleFactor }} ×</b><input v-model.number="form.upscaleFactor" type="range" min="1" :max="['Proteus Natural','Gaia 2'].includes(form.enhanceModel) ? 2 : 4" step="0.5" :aria-label="vt(&quot;视频放大倍率&quot;)"/></label><details><summary>{{ vt("再打磨一点细节") }}</summary><label class="qv-check"><input v-model="form.customEnhance" type="checkbox"/>{{ vt("自己调整细节") }}</label><p class="qv-muted">{{ vt("未开启时沿用模型的默认处理。") }}</p><label v-for="control in [{key:'compression',label:'压缩痕迹修复',max:1},{key:'noise',label:'减少噪点',max:1},{key:'halo',label:'减少光晕',max:1},{key:'grain',label:'胶片颗粒',max:0.1},{key:'recoverDetail',label:'保留原片细节',max:1}]" :key="control.key" class="qv-field">{{ vt(control.label) }} <b>{{ form[control.key] }}</b><input v-model.number="form[control.key]" type="range" min="0" :max="control.max" step="0.01" :aria-label="vt(control.label)" :disabled="!form.customEnhance"/></label></details><p class="qv-muted">{{ vt("按原片时长及放大面积核对本次次数。精修会另存一条作品。") }}</p></fieldset>
        <fieldset v-if="form.mode === 'lipsync'" class="qv-tools-parameters"><legend>{{ vt("让声音，贴着画面走") }}</legend><label class="qv-field">{{ vt("画面与声音长度不同时") }}<select v-model="form.syncMode" :aria-label="vt(&quot;口型时长处理&quot;)"><option v-for="mode in syncModes" :key="mode.key" :value="mode.key">{{ vt(mode.label) }}</option></select></label><p class="qv-muted">{{ vt("按两份素材中较长的一段核对次数。清晰的单人脸近景与干净人声，通常更容易对齐表情。") }}</p></fieldset>
        <div v-if="form.mode === 'extend'" class="qv-source-choice"><b>{{ sourceTask ? vt("接着这一条，继续讲") : vt("先选一条自己的成片") }}</b><p>{{ sourceTask?.prompt || vt("在我的片库打开一条可续写的成片，选择「续写下一幕」。") }}</p><button v-if="sourceTask" type="button" @click="sourceTask = null">{{ vt("重新选择") }}</button></div>
        <p v-if="legacyExtend" class="qv-muted">{{ vt("兼容续写保留来源描述、风格和运镜，接着原场景延长。") }}</p><fieldset v-if="!['upscale','lipsync'].includes(form.mode)" class="qv-parameters" :disabled="legacyExtend"><div class="qv-pair"><label class="qv-field">{{ vt("画幅") }}<select v-model="form.ratio" :aria-label="vt(&quot;视频画幅&quot;)"><option v-for="r in allowedRatios" :key="r" :value="r">{{ r === 'adaptive' || r === 'source' ? vt("跟随参考画面") : r }}</option></select></label><label class="qv-field">{{ vt("时长") }}<select v-model.number="form.seconds" :aria-label="vt(&quot;视频时长&quot;)"><option v-for="s in timeChoices" :key="s" :value="s">{{ s ? vt("{p0} 秒",{p0:(s)}) : form.mode === 'edit' ? vt("跟随原片") : vt("服务方默认") }}</option></select></label></div>
        <label v-if="selected?.features.resolutions?.length" class="qv-field">{{ vt("清晰度") }}<select v-model="form.resolution" :aria-label="vt(&quot;视频清晰度&quot;)"><option v-for="r in selected.features.resolutions" :key="r" :value="r">{{ r }}</option></select></label>
        <details class="qv-advanced"><summary>{{ vt("风格与镜头设置 ") }}<span>＋</span></summary><div v-if="selected?.features.camera" class="qv-camera"><label class="qv-field">{{ vt("画面风格") }}<select v-model="form.style" :aria-label="vt(&quot;视频风格&quot;)"><option value="">{{ vt("由描述决定") }}</option><option v-for="s in selected.features.styles" :key="s.key" :value="s.key">{{ vt(s.label) }}</option></select></label><div class="qv-pair"><label v-for="c in cameraChoices" :key="c.key" class="qv-field">{{ vt(c.label) }}<select v-model="form[c.key]" :aria-label="vt(c.label)"><option value="">{{ vt("自动") }}</option><option v-for="v in c.values" :key="v.key" :value="v.key">{{ vt(v.label) }}</option></select></label></div><label class="qv-field">{{ vt("运动幅度 ") }}<b>{{ form.motion }}</b><input v-model.number="form.motion" :aria-label="vt(&quot;运动幅度&quot;)" type="range" min="1" max="4" step="1" /></label><div class="qv-pair"><label class="qv-field">{{ vt("帧率") }}<input v-model.number="form.frameRate" :aria-label="vt(&quot;视频帧率&quot;)" type="number" min="1" max="24" /></label><label class="qv-field">{{ vt("描述贴合度") }}<input v-model.number="form.guidanceScale" :aria-label="vt(&quot;描述贴合度&quot;)" type="number" min="5" max="25" /></label></div><label class="qv-field">{{ vt("不希望出现的元素") }}<textarea v-model="form.negativePrompt" :aria-label="vt(&quot;视频负向提示词&quot;)" rows="2" maxlength="2000"></textarea></label></div><label class="qv-field">{{ vt("随机种子") }}<input v-model="form.seed" :aria-label="vt(&quot;视频随机种子&quot;)" type="number" min="0" max="4294967295" :placeholder="vt(&quot;留空，让想象自由生长&quot;)" /></label><label v-if="selected?.features.sound" class="qv-check"><input v-model="form.sound" type="checkbox" />{{ vt("生成同步声音") }}</label><p v-if="!selected?.features.camera" class="qv-muted">{{ vt("用描述表达运镜、风格和不希望出现的内容。此模型不单独接收运镜选项。") }}</p></details></fieldset>
        <button type="button" class="qv-primary qv-generate" :disabled="!selected?.ready || quoting || submitting || uploading || materialBusy || galleryEntry.blocked" @click="prepareQuote"><BrandLoader v-if="quoting || submitting" :size="20" /><span>{{ quoting ? vt("核对这一幕…") : submitting ? vt("正在开机…") : ({reference:vt("让素材成为下一幕"),edit:vt("开始改写"),upscale:vt("开始精修"),lipsync:vt("开始口型同步")}[form.mode] || vt("让这一幕动起来")) }}</span><span>↗</span></button><p class="qv-cost">{{ estimate }}</p><p class="qv-muted">{{ vt("提交后可以离开页面，稍后回来查看成片。") }}</p>
      </template>
    </section>
    <section class="qv-library" :aria-label="vt(&quot;视频片库&quot;)"><div v-if="pendingIntent" class="qv-recovery" role="status"><b>{{ vt("上一条提交等待确认") }}</b><p>{{ vt("先找回提交结果，避免同一条创意重复开机。") }}</p><button type="button" :disabled="recovering" @click="recoverIntent">{{ recovering ? vt("正在找回…") : vt("找回这次提交") }}</button><button type="button" :disabled="recovering" @click="retryIntent">{{ vt("再次确认原提交") }}</button></div><header class="qv-library-head"><div role="tablist" :aria-label="vt(&quot;视频作品来源&quot;)"><button type="button" role="tab" :aria-selected="tab === 'mine'" @click="tab = 'mine'">{{ vt("我的片库 ") }}<b v-if="tab === 'mine'">{{ total }}</b></button><button type="button" role="tab" :aria-selected="tab === 'square'" @click="tab = 'square'">{{ vt("灵感放映厅") }}</button><button type="button" role="tab" :aria-selected="tab === 'trash'" @click="tab = 'trash'">{{ vt("回收站") }}</button></div><button type="button" class="qv-icon-button" :aria-label="vt(&quot;刷新视频片库&quot;)" :disabled="loading" @click="loadTasks"><ClientIcon name="refresh" /></button></header>
      <div v-if="listError" class="qv-alert" role="alert">{{ vt(listError) }}<button type="button" @click="loadTasks">{{ vt("再试一次") }}</button></div><BrandLoader v-if="loading && !tasks.length" :text="vt(&quot;正在展开你的片库…&quot;)" />
      <div v-else-if="tab === 'trash' && !tasks.length && !listError" class="qv-empty"><h2>{{ vt("回收站很干净。") }}</h2><p>{{ vt("移入这里的成片可以恢复，恢复后仅自己可见。") }}</p></div><div v-else-if="!tasks.length && !listError" class="qv-empty"><div class="qv-empty-frame" aria-hidden="true"><span>▶</span><i>Q / TAKE 01</i></div><span class="qv-eyebrow">SMALL IDEA, MOVING WORLD</span><h2>{{ vt("好故事，") }}<em>{{ vt("从这一帧开始。") }}</em></h2><p>{{ vt("写下一个画面，让光影、风和时间一起加入创作。") }}</p><div class="qv-ideas"><button v-for="idea in ideas" :key="idea.title" type="button" @click="form.prompt = vt(idea.prompt)"><i>{{ idea.icon }}</i><b>{{ vt(idea.title) }}</b><small>{{ vt(idea.tag) }}</small><span>↗</span></button></div></div>
      <div v-else class="qv-grid"><article v-for="task in tasks" :key="task.id" class="qv-card"><button v-if="tab !== 'trash' && task.status === 'SUCCESS'" type="button" class="qv-poster" :aria-label="vt(&quot;播放视频：{p0}&quot;,{p0:(task.prompt)})" @click="openDetail(task)"><img v-if="media.get(task.id)?.posterUrl" :src="media.get(task.id).posterUrl" :alt="task.prompt" @error="posterFailed(task.id)" /><span class="qv-poster-gradient" v-else></span><span class="qv-play">▶</span><small>{{ task.seconds ? vt("{p0} 秒",{p0:(task.seconds)}) : 'QGAUSS FILM' }}</small></button><div v-else class="qv-processing"><BrandLoader v-if="videoActive(task.status)" :size="42" /><ClientIcon v-else name="video" /><b>{{ vt(videoStatus(task.status)) }}</b><p>{{ videoTaskMessage(task,vt) || vt("灵感正在一点点成形。") }}</p><progress v-if="videoActive(task.status)" :value="task.progress || undefined" max="100" :aria-label="vt(videoStatus(task.status))"></progress></div><div class="qv-card-body"><div class="qv-card-meta"><span :data-status="task.status">{{ vt(videoStatus(task.status)) }}</span><small>{{ task.published ? vt("已公开") : task.mine === false ? task.author : vt("仅自己可见") }}</small></div><h3>{{ task.prompt }}</h3><p>{{ task.presetName }} · {{ task.ratio === 'source' ? vt("保留原片画幅") : task.ratio === 'adaptive' ? vt("跟随画面") : task.ratio }}{{ task.resolution ? ' · ' + task.resolution : '' }}</p><footer><button v-if="tab === 'trash'" type="button" :disabled="busy.has(task.id)" @click="restoreTask(task)">{{ vt("恢复到我的片库 ↗") }}</button><template v-else><button type="button" @click="openDetail(task)">{{ vt("查看这一幕 ↗") }}</button><button v-if="task.mine !== false && ['QUEUED','SUBMITTING','POLLING'].includes(task.status)" type="button" :disabled="busy.has(task.id)" @click="stopTask(task)">{{ vt("停止等待") }}</button><button v-else-if="!videoActive(task.status)" type="button" @click="reuse(task)">{{ vt("带着灵感再创作") }}</button></template></footer></div></article></div>
      <nav v-if="total > pageSize" class="qv-pages" :aria-label="vt(&quot;视频分页&quot;)"><button type="button" :disabled="loading || page <= 1" @click="page--; loadTasks()">{{ vt("← 上一页") }}</button><span>{{ page }} / {{ Math.ceil(total / pageSize) }}</span><button type="button" :disabled="loading || page * pageSize >= total" @click="page++; loadTasks()">{{ vt("下一页 →") }}</button></nav><p class="qv-archive">QGAUSS CREATIVE ARCHIVE <span>{{ vt("把灵感，留在时间里。") }}</span></p>
    </section>
    <Teleport to="body"><dialog ref="confirmDialog" class="qv-dialog qv-confirm" aria-labelledby="qv-confirm-title" @cancel.prevent="closeConfirm"><span class="qv-eyebrow">QGAUSS / READY, SET, ACTION</span><h2 id="qv-confirm-title">{{ vt("准备好，") }}<em>{{ vt("开机了吗？") }}</em></h2><p>{{ quotePayload?.prompt }}</p><ul v-if="quote?.materials?.length" class="qv-confirm-materials"><li v-for="(material,index) in quote.materials" :key="index">{{ ({image:vt("画面"),video:vt("视频"),audio:vt("声音")})[material.kind] }} · {{ material.filename }}<small v-if="material.duration">{{ vt(" · {p0} 秒",{p0:(Number(material.duration).toFixed(1))}) }}</small></li></ul><div v-if="quotePayload?.mode==='lipsync'" class="qsp-saved"><span aria-hidden="true">◎</span><p>{{ speakerCaption(quote?.speakerSelection,quote?.materials?.find(x=>x.kind==='video'),vt) }}<small>{{ vt("本次确认使用这里保存的人物与画面。") }}</small></p></div><p v-if="quote?.followsSource" class="qv-muted">{{ vt("按素材核对 {p0} 秒{p1}",{p0:(quote.seconds),p1:(quote.multiplier > 1 ? vt(" · 放大面积 {p0} 倍",{p0:(quote.multiplier)}) : '')}) }}</p><dl><div><dt>{{ vt("本次创作") }}</dt><dd>{{ quote?.name }}</dd></div><div><dt>{{ vt("本次预留") }}</dt><dd>{{ quoteReady ? quote.cost : '—' }} {{ videoPoolLabel(quote?.pool,quote?.cost,vt) || vt("次数") }}</dd></div></dl><p class="qv-muted">{{ vt("完成并保存后结算本次约定次数；未完成会释放预留，过期权益按原规则处理。参考素材将发送给所选视频服务。") }}</p><div class="qv-dialog-actions"><button type="button" :disabled="submitting" @click="closeConfirm">{{ vt("再想一想") }}</button><button type="button" class="qv-primary" :disabled="submitting || !quoteReady" @click="confirmCreate">{{ submitting ? vt("正在开机…") : vt("确认开始创作") }}</button></div></dialog>
    <dialog ref="detailDialog" class="qv-dialog qv-detail" aria-labelledby="qv-detail-title" @cancel.prevent="closeDetail" @close="stopPlayer"><header><div><span class="qv-eyebrow">QGAUSS / PRIVATE SCREENING</span><h2 id="qv-detail-title">{{ vt("这一幕，值得停留。") }}</h2></div><button type="button" class="qv-icon-button" :aria-label="vt(&quot;关闭视频详情&quot;)" @click="closeDetail">×</button></header><BrandLoader v-if="detailLoading" :text="vt(&quot;正在准备放映…&quot;)" /><template v-else-if="detail"><div class="qv-player"><video v-if="detail.status === 'SUCCESS' && detailMedia?.videoUrl" ref="player" :src="detailMedia.videoUrl" :poster="detailMedia.posterUrl || undefined" controls playsinline preload="metadata" :aria-label="vt(&quot;成片播放器&quot;)" @error="playError = '成片暂未播放，链接可能已过期，请刷新播放地址。'" @loadedmetadata="resumePlayer"></video><div v-else class="qv-player-status"><BrandLoader v-if="videoActive(detail.status)" /><b>{{ vt(videoStatus(detail.status)) }}</b><p>{{ videoTaskMessage(detail,vt) }}</p></div></div><div v-if="playError" class="qv-alert" role="alert">{{ vt(playError) }}<button type="button" @click="refreshPlayback">{{ vt("刷新播放地址") }}</button></div><div class="qv-detail-info"><div><span class="qv-status">{{ vt(videoStatus(detail.status)) }}</span><h3>{{ vt("画面里的想法") }}</h3><p>{{ detail.prompt }}</p><div class="qv-specs"><span>{{ detail.presetName }}</span><span>{{ detail.ratio==='source'?vt("保留原片画幅"):detail.ratio==='adaptive'?vt("自适应画幅"):detail.ratio }}</span><span v-if="detail.seconds">{{ vt("{p0} 秒",{p0:(detail.seconds)}) }}</span><span>{{ detail.resolution }}</span><span v-if="detail.seed !== null && detail.seed !== undefined">{{ vt("种子 {p0}",{p0:(detail.seed)}) }}</span></div></div><VideoBilling v-if="detail.mine" :billing="detail.billing" /></div><div v-if="detail.mine && detail.mode==='lipsync'" class="qsp-saved"><span aria-hidden="true">◎</span><p>{{ speakerCaption(detail.params?.speakerSelection,detail.materials?.find(x=>x.kind==='video'),vt) }}<small>{{ vt("带回创作时，会同时带回本人素材和人物选择。") }}</small></p></div><div class="qv-detail-buttons"><button v-for="tool in [{key:'upscale',label:'放大更清晰'},{key:'lipsync',label:'给这一幕配音'},{key:'edit',label:'改写这一幕'}].filter(x=>detail.mine && detail.status === 'SUCCESS' && presets.some(p=>p.ready && p.features.modes.includes(x.key)))" :key="tool.key" type="button" :disabled="materialBusy" @click="beginTool(detail,tool.key)">{{ vt(tool.label) }} ↗</button><button v-if="detail.status === 'SUCCESS'" type="button" class="qv-primary" :disabled="downloading" @click="downloadMovie">{{ downloading ? vt("准备下载…") : vt("下载成片") }} ↓</button><button type="button" @click="reuse(detail)">{{ vt("带着灵感再创作") }}</button><button v-if="detail.mine && detail.canExtend && detail.status === 'SUCCESS'" type="button" @click="extend(detail)">{{ vt("续写下一幕 ↗") }}</button><button v-if="detail.mine && detail.status === 'SUCCESS'" type="button" :disabled="busy.has(detail.id)" @click="publishConfirm = true">{{ detail.published ? vt("撤回公开") : vt("发布到放映厅") }}</button><button v-if="detail.mine && !videoActive(detail.status)" type="button" :disabled="busy.has(detail.id)" @click="deleteConfirm = true">{{ vt("移入回收") }}</button><button v-if="detail.mine && ['QUEUED','SUBMITTING','POLLING'].includes(detail.status)" type="button" :disabled="busy.has(detail.id)" @click="stopTask(detail)">{{ vt("停止等待") }}</button></div><ArtworkPublication v-if="publishConfirm && detail.mine" class="qv-inline-confirm" kind="video" :work="detail" :categories="publishCats" @updated="publicationUpdated" @cancel="publishConfirm = false" /><div v-if="deleteConfirm" class="qv-inline-confirm"><p>{{ vt("移入回收后将从片库和放映厅隐藏，已有费用不改变。") }}</p><button type="button" :disabled="busy.has(detail.id)" @click="removeTask">{{ vt("确认移入回收") }}</button><button type="button" @click="deleteConfirm = false">{{ vt("保留成片") }}</button></div><p v-if="detail.mine && ['SUBMITTING','POLLING'].includes(detail.status)" class="qv-muted">{{ vt("停止等待会释放站内预留；服务方仍可能继续计算或产生外部费用。") }}</p><details v-if="deta