}});
async function loadOptions() { const req = scope('options'); optionsError.value = ''; try { const data = await api.get('/video/options', { signal: req.signal }); if (!req.current()) return; presets.value = data.presets || []; publishCats.value = data.cats || []; optionsLoaded.value = true; if (!form.presetId) form.presetId = presets.value.find(p => p.ready)?.id || presets.value[0]?.id || ''; } catch (e) { if (req.current()) optionsError.value = e.message || '片场参数暂未打开'; } }
