async function loadMedia(id, force = false) { if (!force && media.has(id)) return media.get(id); const req = scope('media:' + id); try { const data = await api.get('/video/tasks/' + encodeURIComponent(id) + '/playback', { signal: req.signal }); if (!req.current()) return null; media.set(id, data); return data; } catch { return null; } }
function posterFailed(id) { const value = media.get(id); if (value) media.set(id, { ...value, posterUrl: null }); }
function clearReferences() { controllers.get('upload')?.abort(); uploading.value = false; references.value = []; for (const url of localUrls.values()) URL.revokeObjectURL(url); localUrls.clear(); assets.retain(new Set()); }
function removeReference(index) { const removed = references.value.splice(index, 1)[0]; if (removed && localUrls.has(removed.id)) { URL.revokeObjectURL(localUrls.get(removed.id)); localUrls.delete(removed.id); } assets.retain(new Set(references.value.map(i => '/api/upload/' + i.id + '/raw'))); }
async function uploadReferences(event) { const files = [...event.target.files || []]; event.target.value = ''; if (!files.length || uploading.value) return; if (references.value.length + files.length > (selected.value?.features.maxImages || 1)) return ElMessage.warning(vt('当前创作方式的参考图数量已达上限')); if (files.some(f => !/^image\/(png|jpeg|webp|gif)$/.test(f.type) || f.size > 10 * 1024 * 1024)) return ElMessage.warning(vt('请选择不超过 10 MB 的静态图片')); const req = scope('upload'); uploading.value = true; try { for (const file of files) { const value = await uploadFile(file, { signal: req.signal }); if (!req.current()) return; localUrls.set(value.id, URL.createObjectURL(file)); references.value.push({ id: value.id, name: file.name }); } } catch (e) { if (req.current()) ElMessage.error(vt(e.message || '参考图上传失败')); } finally { if (req.current()) uploading.value = false; } }
