async function prepareQuote() { if(galleryEntry.blocked)return; if (quoting.value || submitting.value || uploading.value || materialBusy.value) return; if (pendingIntent.value) return ElMessage.warning(vt('请先确认上一条提交的结果')); let data; try { data = payload(); } catch (e) { return ElMessage.warning(vt(e.message)); } const req = scope('quote'); quote.value=null;quotePayload.value=null;quoting.value = true; try { const result = await api.post('/video/quote', data, { signal: req.signal }); if (!req.current()) return; if(!videoQuoteReady(result,data))throw Error('本次费用尚未确认，请重新核对后再开机。');quote.value = result; quotePayload.value = data; confirmDialog.value.showModal(); } catch (e) { if (req.current()) ElMessage.error(vt(e.message)); } finally { if (req.current()) quoting.value = false; } }
