async function recoverIntent() { if (!pendingIntent.value || recovering.value) return; const req = scope('recover'); recovering.value = true; try { const task = await api.get('/video/tasks/by-request/' + pendingIntent.value.requestKey, { signal: req.signal }); if (req.current()) await accepted(task); } catch (e) { if (req.current()) ElMessage.warning(vt(e.status === 404 ? '暂未找到这次提交，可再次确认原提交；同一意图不会重复创建。' : '暂时无法找回，请稍后再试。')); } finally { if (req.current()) recovering.value = false; } }
async function retryIntent() { if(galleryEntry.blocked)return; if (!pendingIntent.value || recovering.value) return; const req = scope('retry'); recovering.value = true; try { const data = await api.post('/video/quote', pendingIntent.value.payload, { signal: req.signal }); if (!req.current()) return; if(!videoQuoteReady(data,pendingIntent.value.payload))throw Error('本次费用尚未确认，请重新核对后再开机。');quote.value = data; quotePayload.value = pendingIntent.value.payload; confirmDialog.value.showModal(); } catch (e) { if (req.current()) ElMessage.error(vt(e.message)); } finally { if (req.current()) recovering.value = false; } }
async function refreshDetail(id, revision) { const req = scope('detail'); try { const row = await api.get('/video/tasks/' + encodeURIComponent(id), { signal: req.signal }); if (!req.current() || detailRevision !== revision) return; detail.value = row; if (row.status === 'SUCCESS') { const value = await loadMedia(id, true); if (req.current() && detailRevision === revision) detailMedia.value = value; } } catch (e) { if (req.current() && detailRevision === revision) detailError.value = e.message; } }
async function openDetail(task) { resumeAt = 0; opener = document.activeElement; detailLoading.value = true; detailError.value = ''; detail.value = null; detailMedia.value = null; playError.value = ''; publishConfirm.value = deleteConfirm.value = false; detailDialog.value.showModal(); const revision = ++detailRevision; await refreshDetail(task.id, revision); if (current() && revision === detailRevision) detailLoading.value = false; }
function stopPlayer() { const element = player.value; if (element) { element.pause(); element.removeAttribute('src'); element.load(); } }
function closeDetail() { resumeAt = 0; ++detailRevision; controllers.get('detail')?.abort(); stopPlayer(); detailDialog.value?.close(); detail.value = null; detailMedia.value = null; opener?.focus?.({ preventScroll: true }); }
async function refreshPlayback() { if (!detail.value) return; const id = detail.value.id, revision = detailRevision; resumeAt = player.value?.currentTime || 0; playError.value = ''; const value = await loadMedia(id, true); if (current() && revision === detailRevision) { detailMedia.value = value; if (!value) playError.value = '暂时无法打开成片，请稍后重试。'; } }
function resumePlayer() { if (player.value && resumeAt > 0 && Number.isFinite(player.value.duration)) player.value.currentTime = Math.min(resumeAt, Math.max(0, player.value.duration - .1)); resumeAt = 0; }
function reuse(task) { form.prompt = task.prompt || ''; form.presetId = presets.value.some(p => p.id === task.presetId) ? task.presetId : form.presetId; form.mode = 'text'; form.ratio = task.ratio || '16:9'; form.seconds = task.params?.seconds ?? task.seconds ?? selected.value?.features.seconds?.[0] ?? 0; form.resolution = task.resolution || '720p'; form.seed = task.seed ?? ''; for (const key of ['style','motion','guidanceScale','frameRate','pan','tilt','rotate','zoom','negativePrompt','sound']) if (task.params?.[key] !== undefined) form[key] = task.params[key]; sourceTask.value = null; clearReferences(); materials.value=[];speakerSelection.value=null; if(videoToolMode(task.mode)){form.mode=task.mode;materials.value=task.mine?(task.materials||[]):[];if(task.mine&&validSpeaker(task.params?.speakerSelection,materials.value.find(x=>x.kind==='video')))speakerSelection.value={...task.params.speakerSelection};for(const key of ['upscaleFactor','enhanceModel','syncMode','compression','noise','halo','grain','recoverDetail'])if(task.params?.[key]!==undefined)form[key]=task.params[key];form.customEnhance=['compression','noise','halo','grain','recoverDetail'].some(k=>task.params?.[k]!==undefined);} if (task.mine && task.mode==='image' && task.imageIds?.length) { form.mode = 'image'; references.value = task.imageIds.map(id => ({ id })); for (const id of task.imageIds) void assets.load({ url: '/api/upload/' + id + '/raw' }); } closeDetail(); nextTick(() => { if (current()) document.querySelector('#qv-prompt')?.focus(); }); }
async function beginTool(task,mode){const preset=presets.value.find(p=>p.ready&&p.features.modes.includes(mode));if(!preset)return ElMessage.warning(vt('先在视频控制台准备支持这项处理的连接'));const request=scope('tool-source');materialBusy.value=true;try{const item=await api.post('/video/materials/from-task/'+encodeURIComponent(task.id),{}, {signal:request.signal});if(!request.current())return;form.presetId=preset.id;form.mode=mode;form.prompt='';speakerSelection.value=null;materials.value=[{...item,kind:'video'}];closeDetail();nextTick(()=>{if(current())document.querySelector('#qv-prompt')?.focus();});}catch(e){if(request.current())ElMessage.error(vt(e.message));}finally{if(request.current())materialBusy.value=false;}}
function extend(task) { if (!task.mine || !task.canExtend) return; reuse(task); form.mode = 'extend'; sourceTask.value = task; form.prompt = selected.value?.profile === 'PIKA_1' ? task.prompt : ''; }
async function stopTask(task) { if (busy.has(task.id)) return; busy.add(task.id); try { const value = await api.post('/video/tasks/' + task.id + '/cancel'); if (!current()) return; if (detail.value?.id === task.id) detail.value = value; await loadTasks();if(current()){const updated=tasks.value.find(row=>row.id===task.id);if(!updated||feeSignature(updated)===feeSignature(task))refreshCredits();} ElMessage.success(vt(value.status === 'SUCCESS' ? '这一幕已完成，成片与结算结果已保留。' : '已停止等待，未结算的预留已处理。')); } catch (e) { if (current()) ElMessage.error(vt(e.message)); } finally { if (current()) busy.delete(task.id); } }
async function publicationUpdated(value) { if(!current()||detail.value?.id!==value.id)return;Object.assign(detail.value,value);await loadTasks(); }
async function removeTask() { const task = detail.value; if (!task || busy.has(task.id)) return; busy.add(task.id); try { await api.del('/video/tasks/' + task.id); if (!current()) return; closeDetail(); await loadTasks(); } catch (e) { if (current()) ElMessage.error(vt(e.message)); } finally { if (current()) busy.delete(task.id); } }
async function restoreTask(task) { if (busy.has(task.id)) return; busy.add(task.id); try { await api.post('/video/tasks/' + task.id + '/restore'); if (!current()) return; await loadTasks(); ElMessage.success(vt('已恢复到我的片库，仅自己可见。')); } catch (e) { if (current()) ElMessage.error(vt(e.message)); } finally { if (current()) busy.delete(task.id); } }
async function downloadMovie() { if (!detail.value || downloading.value) return; downloading.value = true; const id = detail.value.id, revision = detailRevision; try { const value = await loadMedia(id, true); if (!value || !current() || revision !== detailRevision) return; const link = document.createElement('a'); link.href = value.downloadUrl; link.download = 'QGauss-film-' + id.slice(-10) + '.mp4'; document.body.append(link); link.click(); link.remove(); } finally { if (current()) downloading.value = false; } }
function normalize() { if(galleryEntry.applied&&form.presetId===galleryEntry.sourceDraft?.presetId)return; const p = selected.value; if (!p) return; if (!p.features.modes.includes(form.mode)) form.mode = p.features.modes[0] || 'text'; if (!allowedRatios.value.includes(form.ratio)) form.ratio = allowedRatios.value[0]; if (!timeChoices.value.includes(form.seconds)) form.seconds = timeChoices.value[0]; if (!p.features.resolutions.includes(form.resolution)) form.resolution = p.features.resolutions[0] || ''; }
watch([selected, () => form.mode], normalize); watch(tab, () => { page.value = 1; void loadTasks(); });
function dispose() { if (!alive) return; alive = false; clearInterval(timer); for (const controller of controllers.values()) controller.abort(); stopPlayer(); detailDialog.value?.close(); confirmDialog.value?.close(); for (const url of localUrls.values()) URL.revokeObjectURL(url); localUrls.clear(); assets.close(); media.clear(); }
watch(() => auth.user?.id, value => { if (value !== owner) { intentStore.clear(); dispose(); } });
onMounted(async () => { await Promise.all([loadOptions(), loadTasks()]);await nextTick();galleryBaseline=JSON.stringify(form);if(current())void galleryEntry.initialize(); if (current()) { refreshCredits(); if (pendingIntent.value) void recoverIntent(); timer = setInterval(() => { if (current() && !loading.value && (activeCount.value || detail.value && videoActive(detail.value.status))) void loadTasks(); }, 3500); } });
onUnmounted(dispose);
</script>
